import{_ as t,o as r,c as n,ag as a}from"./chunks/framework.BtBS1okS.js";const m=JSON.parse(`{"title":"Votre rôle de manager","description":"","frontmatter":{},"headers":[],"relativePath":"handout-07-cloture.md","filePath":"handout-07-cloture.md","handout":{"fichier":"handout-07-cloture.md","markdown":"# Handout — Votre rôle de manager\\n\\n**Le nouveau PDLC IA — ce qui change pour votre équipe · Zenika · fiche module 7**\\n\\nCe que fait un manager quand son équipe entre dans le nouveau cycle : les postures, les questions à poser, ce qu'on évite, trois risques à surveiller et la liste des 30 premiers jours.\\n\\n## Votre rôle de manager\\n\\n_Module 7 · slide « Votre rôle de manager »_\\n\\n| Posture                                | Ce que ça veut dire                                                                                               | Pourquoi                                                                                   |\\n| -------------------------------------- | ----------------------------------------------------------------------------------------------------------------- | ------------------------------------------------------------------------------------------ |\\n| **Vous questionnez, l'équipe décide**  | Vous ne codez pas, n'activez pas un flag, ne signez pas à sa place                                                | Sinon, la trace nomme quelqu'un qui n'a pas décidé, et l'équipe perd la main sur ses choix |\\n| **Deux questions suffisent**           | « Qui l'a décidé ? Qui signe ? »                                                                                  | Elles révèlent ce qui manque : un responsable, un seuil, une source                        |\\n| **Un NO-GO n'est pas une sanction**    | Il nomme un critère : l'équipe corrige, revérifie, redemande. Commentez aussi les GO : « vous passez parce que… » | Une gate qui renvoie avec un critère fait progresser ; une gate qui punit fait cacher      |\\n| **Quand ça coince, regardez le cadre** | Le format, la gate, le contexte ; un profil qui manque se signale comme un écart à combler                        | On améliore le cadre ; on lit les résultats par équipe, jamais par personne                |\\n| **Pas de vitesse sans qualité**        | Un gain de vitesse ne compte que si la gate suivante passe au vert                                                | Une vitesse payée en qualité n'est pas un gain                                             |\\n\\n> L'agent propose, les humains décident.\\n\\n## Les questions à poser à l'équipe\\n\\n_Module 7 · slide « Votre rôle de manager »_\\n\\n- **Qui l'a décidé ? Qui signe ?**\\n- **Comment saurez-vous dans 30 jours que ça a marché ?** Et qui a fixé ce seuil ?\\n- **Ce test couvre quel critère d'acceptation ?**\\n- **Quelle version du contrat de l'autre équipe utilisez-vous ?**\\n- **Qui active la fonctionnalité, et comment revient-on en arrière ?**\\n- **Qu'est-ce qui est encore incertain ?** L'équipe écrit « à confirmer » ce qui n'est pas sûr, au lieu de le deviner.\\n- **Après un changement : la spec est-elle à jour avant le code ?**\\n- **Les critères de la gate étaient-ils clairs ?** Lequel l'était le moins ?\\n\\nQuand l'équipe dit « ce n'est pas comme chez nous » : on le note, on ne le débat pas. Ces remarques font évoluer le cycle.\\n\\n## Ce qu'on évite\\n\\n_Module 7 · slide « Votre rôle de manager »_\\n\\n- Taper, activer un flag ou signer à la place de l'équipe.\\n- Répondre avant qu'on vous pose la question.\\n- Lever à la place de l'équipe une ambiguïté qu'elle doit faire remonter elle-même.\\n- Modifier le travail d'une autre équipe : on va la voir.\\n- Juger une personne sur un indicateur.\\n- Citer une vitesse sans la qualité qui va avec.\\n- Sauter le retour après une gate : il prend quelques secondes et améliore la gate suivante.\\n\\n## Trois risques à surveiller\\n\\n_Module 7 · slide « Trois risques à surveiller »_\\n\\n| Risque                        | Le signal                                                | Votre réflexe                                                                                   |\\n| ----------------------------- | -------------------------------------------------------- | ----------------------------------------------------------------------------------------------- |\\n| **La charge de relecture**    | Des relectures et des gates qui attendent                | Découper plus petit ; protéger le créneau de relecture                                          |\\n| **L'approbation par réflexe** | Une approbation proche de 100 %, des revues très courtes | Demander « qu'avez-vous refusé cette semaine ? » ; regarder le taux de reprise (module 6)       |\\n| **Les frictions de budget**   | Un budget de tokens dépassé, des sessions abandonnées    | Lire le coût avec la qualité ; une conversation neuve avec l'agent après chaque gate (module 5) |\\n\\n- **La charge de relecture** : la relecture humaine tient jusqu'à un certain volume. Plus l'agent produit, plus elle devient le goulot.\\n- **L'approbation par réflexe** (le « tampon ») : quand presque tout est approuvé, on cesse de lire. Une étape AI-assisted devient alors AI-executed sans que personne l'ait décidé, et sans mesure.\\n- **Les frictions de budget** : on les attend au début, et on les lit au niveau de l'équipe, jamais par personne.\\n\\n> La relecture tient jusqu'à un volume : au-delà, on ne lit plus.\\n\\n## Vos 30 premiers jours\\n\\n_Module 7 · slide « Vos 30 premiers jours »_\\n\\n**Avant que les outils arrivent**\\n\\n| Action                                                                       | Module |\\n| ---------------------------------------------------------------------------- | ------ |\\n| Inscrire l'équipe entière, tous les rôles produit ensemble                   | 4      |\\n| Nommer les quatre casquettes, et connaître votre contact Evaluation Engineer | 4      |\\n| Vérifier que la mesure de référence est prise et l'outil de suivi propre     | 6      |\\n| Vérifier les accès avant les formations                                      | 6      |\\n\\n**Pendant le premier mois**\\n\\n| Action                                                                             | Module |\\n| ---------------------------------------------------------------------------------- | ------ |\\n| Garder un humain sur chaque tâche                                                  | 1 et 2 |\\n| Amorcer le Nexus par les Contracts                                                 | 3      |\\n| Annoncer que la mesure est collective, jamais individuelle                         | 6      |\\n| Prévoir, et dire à l'équipe, plus de relecture et des frictions de budget au début | 5 et 7 |\\n\\n> Protégez le temps de relecture et de décision.\\n\\n**Pour commencer** : entourez une action à lancer dès lundi, et notez une question à rapporter au programme.\\n\\n## Encore à caler\\n\\n_Module 7 · pendant le pilote_\\n\\n- **La limite de la relecture humaine** : aucun critère ne dit encore jusqu'à quel volume un humain relit vraiment.\\n- **Détecter le tampon** : aucune méthode ne repère encore une relecture devenue automatique.\\n- **L'identité des agents en revue** : tant qu'un agent relit sous l'identité d'un humain, la trace nomme quelqu'un qui n'a pas décidé.\\n"}}`),s={name:"handout-07-cloture.md"};function u(i,e,o,l,d,c){return r(),n("div",null,[...e[0]||(e[0]=[a("",30)])])}const q=t(s,[["render",u]]);export{m as __pageData,q as default};
